cd /home/ubuntu/koha-test
echo '' | base64 -d > entrypoint.sh; chmod 755 entrypoint.sh
docker cp -a entrypoint.sh koha-test:/setup/entrypoint.sh
docker restart koha-test >/dev/null; sleep 50
docker ps --filter name=koha-test --format '{{.Status}}'
docker exec koha-test sh -c 'tail -3 /var/log/apache2/error.log | cut -c1-250; tail -3 /var/log/koha/kohadent/plack-intranet-error.log | cut -c1-250'
curl -s -o /dev/null -w "staff %{http_code}\n" -m 30 https://koha.azoclinic.duckdns.org/cgi-bin/koha/mainpage.pl
curl -s -o /dev/null -w "opac %{http_code}\n" -m 30 https://opac.azoclinic.duckdns.org/
